// The gallery's web images, from its masters in tools/out/<id>/ (generated by pictures.mjs, or your own pictures):
//
//   node build.mjs <id>                         site/<id>/img/<item>.webp (900 px, what the gallery shows),
//                                               img/<item>-full.webp (1800 px, loaded when a picture is opened),
//                                               site/<id>/images.json ({ item: { w, h, color } }; color is the
//                                               picture's main colour, shown while it loads) and out/<id>/sheet.jpg
//   node build.mjs <id> --from <folder>         your own pictures instead: every image in the folder, in name order,
//                                               becomes the next item's master (items are added for any left over and
//                                               dropped, with their places in the scenes, when there are fewer)
//
// An item may carry "trim": true (cut off a plain border the model added) or "crop": [left, top, right, bottom] in
// fractions; after either, the picture is cut back to the item's "aspect" from the middle, so every card keeps one shape.
// A picture with no master (one kept from an example) keeps the web images it has.
import sharp from "sharp";
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, extname, join, basename, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { SITE, pageFile, readPage, writePage } from "./page.mjs";

const ROOT = dirname(fileURLToPath(import.meta.url));
const argv = process.argv.slice(2);
const flag = (n) => (argv.includes(n) ? argv[argv.indexOf(n) + 1] : null);
const id = argv.find((a, i) => !a.startsWith("--") && !argv[i - 1]?.startsWith("--"));
if (!id || !existsSync(pageFile(id))) { console.error("usage: node build.mjs <id> [--from <folder of pictures>]   (needs site/<id>/page.json)"); process.exit(1); }
const page = readPage(id);
const OUT = join(ROOT, "out", id), IMG = join(SITE, id, "img"), INFO = join(SITE, id, "images.json");
mkdirSync(OUT, { recursive: true }); mkdirSync(IMG, { recursive: true });
const hex = ({ r, g, b }) => "#" + [r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("");
const pad = (n) => String(n).padStart(2, "0");
const before = existsSync(INFO) ? JSON.parse(readFileSync(INFO, "utf8")) : {};

// ——— your own pictures: copied in as masters, one per item ———
const from = flag("--from");
if (from) {
  const dir = resolve(from.replace(/^~(?=$|\/)/, process.env.HOME || "~"));
  const files = readdirSync(dir).filter((f) => /\.(jpe?g|png|webp|avif|tiff?)$/i.test(f)).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
  if (!files.length) { console.error(`no pictures (jpg, png, webp, avif, tiff) in ${dir}`); process.exit(1); }
  const ratio = (w, h) => { const g = (a, b) => (b ? g(b, a % b) : a), d = g(w, h); return w / d <= 50 ? `${w / d}:${h / d}` : `${(w / h).toFixed(3)}:1`; };
  const named = (f) => basename(f, extname(f)).replace(/[-_]+/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  for (const [k, f] of files.entries()) {
    const src = join(dir, f), { width, height } = await sharp(src).rotate().metadata();
    let it = page.items[k];
    if (!it) page.items.push((it = { id: pad(k + 1), title: named(f), meta: [], text: "" }));
    if (!it.title || /^WRITE/.test(it.title)) it.title = named(f);
    it.aspect = ratio(width, height); delete it.prompt; delete it.trim; delete it.crop;
    await sharp(src).rotate().png().toFile(join(OUT, `${it.id}.png`));
  }
  const dropped = page.items.splice(files.length).map((it) => it.id);
  if (dropped.length) {
    for (const s of page.sequence) {
      if (Array.isArray(s.cards)) s.cards = s.cards.filter((c) => !dropped.includes(c));
      if (Array.isArray(s.looks)) s.looks = s.looks.filter((c) => c === "mix" || !dropped.includes(c));
      if (dropped.includes(s.end)) delete s.end;
    }
    console.log(`dropped items ${dropped.join(", ")} (no picture for them) from the page and its scenes`);
  }
  writePage(id, page);
  console.log(`${files.length} pictures from ${dir} → items ${page.items[0].id}–${page.items.at(-1).id}; give them titles and details in site/${id}/page.json`);
}

// a master as the page uses it: trimmed or cropped, then back to the item's own shape
async function master(it, file) {
  let buf = await sharp(file).toBuffer();
  if (it.trim) buf = await sharp(buf).trim({ threshold: 40 }).toBuffer();
  if (it.crop) {
    const { width: w, height: h } = await sharp(buf).metadata(), [l, t, r, b] = it.crop;
    buf = await sharp(buf).extract({ left: Math.round(w * l), top: Math.round(h * t), width: Math.round(w * (1 - l - r)), height: Math.round(h * (1 - t - b)) }).toBuffer();
  }
  if ((it.trim || it.crop) && it.aspect) {
    const [aw, ah] = it.aspect.split(":").map(Number), { width: w, height: h } = await sharp(buf).metadata();
    const W = Math.min(w, Math.round((h * aw) / ah)), H = Math.min(h, Math.round((w * ah) / aw));
    if (W < w - 2 || H < h - 2) buf = await sharp(buf).extract({ left: (w - W) >> 1, top: (h - H) >> 1, width: W, height: H }).toBuffer();
  }
  return buf;
}

const info = {}, missing = [], shown = {};
for (const it of page.items) {
  const file = join(OUT, `${it.id}.png`), web = join(IMG, `${it.id}.webp`);
  if (!existsSync(file)) {
    // no master: a picture kept from an example keeps its web images and its entry
    if (existsSync(web) && before[it.id]) { info[it.id] = before[it.id]; shown[it.id] = web; } else missing.push(it.id);
    continue;
  }
  const src = await master(it, file);
  const { width, height } = await sharp(src).metadata();
  const { dominant } = await sharp(src).resize(64, 64, { fit: "inside" }).stats();
  info[it.id] = { w: width, h: height, color: hex(dominant) };
  await sharp(src).resize(900, 900, { fit: "inside" }).webp({ quality: 80 }).toFile(web);
  await sharp(src).resize(1800, 1800, { fit: "inside" }).webp({ quality: 84 }).toFile(join(IMG, `${it.id}-full.webp`));
  shown[it.id] = src;
}
writeFileSync(INFO, JSON.stringify(info, null, 1) + "\n");

// the review sheet: every picture, numbered, ten to a row
const CW = 240, CH = 300, GAP = 8, COLS = 10, rows = Math.ceil(page.items.length / COLS), tiles = [];
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
for (const [k, it] of page.items.entries()) {
  const x = (k % COLS) * (CW + GAP), y = Math.floor(k / COLS) * (CH + GAP + 24);
  if (shown[it.id]) tiles.push({ input: await sharp(shown[it.id]).resize(CW, CH, { fit: "contain", background: "#141414" }).toBuffer(), left: x, top: y });
  tiles.push({ input: Buffer.from(`<svg width="${CW}" height="22"><text x="0" y="16" font-family="Helvetica" font-size="13" fill="#ddd">${esc(it.id)} ${esc(it.title || "")}</text></svg>`), left: x, top: y + CH + 2 });
}
await sharp({ create: { width: COLS * (CW + GAP) - GAP, height: rows * (CH + GAP + 24), channels: 3, background: "#141414" } }).composite(tiles).jpeg({ quality: 84 }).toFile(join(OUT, "sheet.jpg"));
console.log(`${id}: ${Object.keys(info).length}/${page.items.length} pictures → site/${id}/img, sheet → tools/out/${id}/sheet.jpg${missing.length ? ` (no picture yet for ${missing.join(", ")})` : ""}`);
